import { NextResponse, type NextRequest } from 'next/server'

interface UpdatePostBody {
  title?: string
  content?: string
}

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function GET(_request: NextRequest, ctx: RouteContext) {
  const { id } = await ctx.params

  // Simulate fetching a single post
  const post = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post)
}

export async function PUT(request: NextRequest, ctx: RouteContext) {
  const { id } = await ctx.params

  let body: UpdatePostBody
  try {
    body = await request.json()
  } catch {
    body = {}
  }

  const { title, content } = body

  // Simulate updating a post
  const updatedPost = {
    id: parseInt(id),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(_request: NextRequest, ctx: RouteContext) {
  const { id } = await ctx.params

  // Simulate deleting a post
  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}

